const openStrings=[64,59,55,50,45,40];
function voice(n,t,d,v,kind,bus,style='pop'){
 if(v<=0)return;d=Math.max(.04,d);const a=audio,f=hz(n),out=a.createGain(),filter=a.createBiquadFilter();filter.type='lowpass';filter.frequency.value=kind==='bass'?850:kind==='keys'?4400:style==='rock'?3900:2900;out.gain.setValueAtTime(.0001,t);out.gain.exponentialRampToValueAtTime(v,t+.009);out.gain.exponentialRampToValueAtTime(Math.max(.0002,v*.35),t+Math.min(d*.45,.16));out.gain.exponentialRampToValueAtTime(.0001,t+d);filter.connect(out);out.connect(bus||a.destination);
 let dest=filter;if(kind==='guitar'&&style==='rock'){const sh=a.createWaveShaper(),curve=new Float32Array(512);for(let i=0;i<512;i++)curve[i]=Math.tanh((i/255.5-1)*2.4);sh.curve=curve;sh.connect(filter);dest=sh}
 const partials=kind==='bass'?[[1,1],[2,.26],[3,.09]]:kind==='keys'?[[1,1],[2,.36],[3,.16],[4,.08]]:[[1,1],[2,.48],[3,.32],[4,.15],[6,.10]];
 for(const [h,amp] of partials){const o=a.createOscillator(),g=a.createGain();o.frequency.value=f*h;g.gain.value=amp/partials.reduce((s,p)=>s+p[1],0);o.connect(g);g.connect(dest);o.start(t);o.stop(t+d+.02)}
}
const phraseDefs=[{name:'3音で着地',steps:[0,1,2,1],beats:[0,1,2,3]},{name:'上って戻る',steps:[0,1,2,1,0],beats:[0,.5,1,2,3]},{name:'問いかけと答え',steps:[2,1,0,1,0],beats:[0,.5,1.5,2,3]},{name:'ルートへ帰る',steps:[1,2,1,0],beats:[0,1,1.5,3]},{name:'跳ねる3音',steps:[0,2,1,2,0],beats:[0,.75,1.5,2.5,3.5]}];
function positions(lo,hi){return openStrings.flatMap((n,s)=>Array.from({length:hi-lo+1},(_,i)=>({s,f:lo+i,n:n+lo+i})))}
function phraseFor(ch,lo,hi,variant=0){const p=positions(lo,hi),ints=qualities[ch.q]||qualities[''],def=phraseDefs[variant%phraseDefs.length];let prev=null;return def.steps.map((step,i)=>{const pc=mod(ch.r+ints[step%ints.length]),all=p.filter(x=>mod(x.n)===pc);if(!all.length)return null;const center=lo===0?64:64+lo;all.sort((a,b)=>(prev?Math.abs(a.n-prev.n)*2+Math.abs(a.f-prev.f)+Math.abs(a.s-prev.s):Math.abs(a.n-center))-(prev?Math.abs(b.n-prev.n)*2+Math.abs(b.f-prev.f)+Math.abs(b.s-prev.s):Math.abs(b.n-center)));prev=all[0];return {...prev,beat:def.beats[i]}}).filter(Boolean)}
function boardSVG(ch,key,lo,hi,phrase=[],now=null,blues=false,fingers=false){const w=39,span=hi-lo+1,W=38+w*span,hits=new Set(phrase.map(p=>p.s+':'+p.f)),scale=(blues?[0,3,5,6,7,10]:[0,2,4,5,7,9,11]).map(d=>mod(key+d));let h=`<svg viewBox="0 0 ${W} 166" role="img" aria-label="指板・ソロの押弦位置">`;for(let f=lo;f<=hi;f++){let x=37+w*(f-lo);h+=`<text x="${x}" y="12" text-anchor="middle" font-size="11" fill="#53675e">${f}</text><line x1="${x+19}" y1="23" x2="${x+19}" y2="159" stroke="#c5d2ca"/>`;if([3,5,7,9,12,15].includes(f))h+=`<circle cx="${x}" cy="20" r="2" fill="#82968b"/>`}for(let s=0;s<6;s++){let y=34+s*23;h+=`<text x="3" y="${y+3}" font-size="10" fill="#53675e">${s+1}</text><line x1="18" x2="${W-1}" y1="${y}" y2="${y}" stroke="#82968b"/>`;for(let f=lo;f<=hi;f++){let pc=mod(openStrings[s]+f),d=mod(pc-ch.r),hit=(qualities[ch.q]||[]).includes(d),future=hits.has(s+':'+f),cur=now&&now.s===s&&now.f===f;if(!hit&&!scale.includes(pc)&&!future)continue;let fill=!hit?'#fff':d===0?'#ce4b4b':[3,4].includes(d)?'#378657':[6,7,8].includes(d)?'#427ab9':'#9765b4',x=37+w*(f-lo);h+=`<circle cx="${x}" cy="${y}" r="9" fill="${fill}" stroke="${future?'#d69b36':'#a5b9af'}" stroke-width="${future?2:1}"/><text x="${x}" y="${y+3}" font-size="9" text-anchor="middle" fill="${hit?'white':'#53675e'}">${fingers&&future?fingerAt(f,lo):names[pc]}</text>`;if(cur)h+=`<circle cx="${x}" cy="${y}" r="13" fill="none" stroke="#172e27" stroke-width="2.5"/>`}}return h+'</svg>'}
function fingerAt(f,lo){return f===0?'○':['人','中','薬','小'][clamp(f-Math.max(1,lo),0,3)]}function tabHTML(notes,active=-1,fingers=false,lo=0){return `<div class="tabstrip" aria-label="押弦順">${notes.map((n,i)=>`<span class="${i===active?'current':''}"><b>${label(n.n)}</b><small>${n.s+1}弦 ${n.f}F${fingers?' ・'+fingerAt(n.f,lo):''}</small><small>${n.beat+1}拍目</small></span>`).join('')}</div><pre class="tablines">${openStrings.map((_,s)=>`${['e','B','G','D','A','E'][s]} |${notes.map(n=>n.s===s?String(n.f).padEnd(3,'-')+'-':'----').join('')}|`).join('\n')}</pre>`}
const instNames=['ドラム','ベース','鍵盤','ギター'];
